    """Base class for all depot errors."""


class NotEnoughFuel(DepotError):
    """Raised when there is not enough fuel to perform an operation."""


class Depot:
    def __init__(self):
        self.tanks = {}
        self.logs = {}

    def add_tank(self, tank_id: str) -> None:
        if tank_id in self.tanks:
            raise DepotError(f"Tank {tank_id} already exists.")
        self.tanks[tank_id] = 0
        self.logs[tank_id] = []

    def fill(self, tank_id: str, litres: int) -> None:
        self._validate_tank_id(tank_id)
        if litres <= 0:
            raise ValueError("Litres must be greater than 0.")
        self.tanks[tank_id] += litres
        self.logs[tank_id].append(("fill", litres))

    def drain(self, tank_id: str, litres: int) -> None:
        self._validate_tank_id(tank_id)
        if litres <= 0:
            raise ValueError("Litres must be greater than 0.")
        if self.tanks[tank_id] < litres:
            raise NotEnoughFuel(f"Not enough fuel in tank {tank_id}.")
        self.tanks[tank_id] -= litres
        self.logs[tank_id].append(("drain", litres))

    def pump(self, from_id: str, to_id: str, litres: int) -> None:
        self._validate_tank_id(from_id)
        self._validate_tank_id(to_id)
        if from_id == to_id:
            raise ValueError("Cannot pump between the same tank.")
        if litres <= 0:
            raise ValueError("Litres must be greater than 0.")
        if self.tanks[from_id] < litres:
            raise NotEnoughFuel(f"Not enough fuel in tank {from_id}.")
        self.tanks[from_id] -= litres
        self.tanks[to_id] += litres
        self.logs[from_id].append(("out", litres))
        self.logs[to_id].append(("in", litres))

    def pump_down(self, from_id: str, to_id: str, keep: int) -> int:
        self._validate_tank_id(from_id)
        self._validate_tank_id(to_id)
        if from_id == to_id:
            raise ValueError("Cannot pump between the same tank.")
        if keep < 0:
            raise ValueError("Keep must be 0 or more.")
        litres_to_move = max(0, self.tanks[from_id] - keep)
        if litres_to_move > 0:
            self.tanks[from_id] -= litres_to_move
            self.tanks[to_id] += litres_to_move
            self.logs[from_id].append(("out", litres_to_move))
            self.logs[to_id].append(("in", litres_to_move))
        return litres_to_move

